        _q('machine-obs-lens', 'Machine Fragment: Dimensional Lens', ['physics.optics', 'math.equations'], 22, 'An ancient lens in the Observatory shows images that appear to come from a different time.', [_s('observe', 'Document what the lens reveals when aimed at different sky regions.', 'Note whether the images match the current sky or differ.'), _s('measure', 'Compare star positions through the lens to current catalog positions.', 'Calculate the angular displacement for each star.'), _s('solve', 'Determine if the displacements are consistent with stellar proper motion over time.', 'Calculate how long ago the stars would have been in the lens positions.'), _s('compare', 'Compare the implied time difference across multiple star fields.', 'A consistent time offset would suggest the lens shows a past sky.')], True),
        _q('machine-obs-signal', 'Machine Fragment: Persistent Signal', ['physics.waves', 'cs.algorithms'], 22, 'The Observatory detects a signal from an ancient device that repeats in a complex mathematical pattern.', [_s('measure', 'Record the signal pattern over an extended period.', 'Note the timing, frequency, and amplitude of each pulse.'), _s('decode', 'Analyze the pulse pattern for mathematical sequences.', 'Look for prime numbers, Fibonacci sequence, or other number patterns.'), _s('pattern', 'Identify the repeating cycle length and predict the next sequence.', 'Once the pattern repeats, calculate its period.'), _s('compare', 'Compare the mathematical content of the signal to known mathematical constants.', 'Check if ratios in the signal correspond to pi, e, or golden ratio.')], True),
        _q('machine-obs-mirror', 'Machine Fragment: Perfect Reflector', ['physics.optics', 'engineering.materials-science'], 22, 'An ancient mirror reflects 100 percent of light across all wavelengths, which is physically impossible.', [_s('measure', 'Measure the reflectivity of the ancient mirror across multiple wavelengths.', 'Use the spectrometer to test reflection at each wavelength.'), _s('compare', 'Compare to the best modern mirrors which typically reflect 95-99 percent.', 'Note at which wavelengths the ancient mirror outperforms modern ones most.'), _s('experiment', 'Test whether the mirror absorbs any energy at all by measuring its temperature under illumination.', 'A perfect reflector would not warm up under light exposure.'), _s('observe', 'Examine the mirror surface at maximum magnification for structural clues.', 'Look for surface features that might explain the unusual reflectivity.')], True),
        _q('machine-obs-clock', 'Machine Fragment: Universal Clock', ['physics.forces', 'math.equations'], 22, 'An ancient timekeeping device maintains perfect accuracy without any visible mechanism.', [_s('measure', 'Compare the ancient clock readings to modern atomic clock standards.', 'Record both readings simultaneously over several days.'), _s('observe', 'Examine the device for any internal components or energy source.', 'Note anything visible about how it keeps time.'), _s('experiment', 'Test whether the clock is affected by temperature, vibration, or magnetic fields.', 'Subject the clock to each condition and check for deviation.'), _s('compare', 'Compare the clock precision to the best modern timekeeping methods.', 'Atomic clocks lose about 1 second per 300 million years.')], True),
        _q('machine-obs-chart', 'Machine Fragment: Star Chart', ['math.coordinate-geometry', 'physics.optics'], 22, 'An ancient star chart shows stars in positions that correspond to no known epoch.', [_s('compare', 'Compare the chart star positions to the current night sky.', 'Note which stars are in different positions and by how much.'), _s('solve', 'Calculate the proper motion needed to explain the position differences.', 'Divide angular displacement by possible time intervals.'), _s('predict', 'Determine when the sky would have matched the chart based on stellar motion rates.', 'Work backward using known proper motion values for bright stars.'), _s('decode', 'Identify any stars on the chart that have no modern counterpart.', 'Check if any charted positions are empty in modern catalogs.')], True),
        _q('machine-obs-gravity', 'Machine Fragment: Gravity Anomaly', ['physics.forces', 'math.equations'], 22, 'An ancient device creates a localized gravity anomaly that measurably affects nearby objects.', [_s('measure', 'Measure gravitational acceleration at various distances from the device.', 'Use a precision accelerometer at marked distances.'), _s('solve', 'Plot gravity vs distance and compare to the expected inverse-square relationship.', 'Normal gravity follows g proportional to 1/r^2.'), _s('experiment', 'Test whether the anomaly affects different masses equally.', 'Drop objects of different mass and measure their acceleration.'), _s('compare', 'Compare the anomaly strength to normal gravitational fields from known masses.', 'Calculate the equivalent mass needed to produce the measured field.')], True),
        _q('machine-obs-spectrum', 'Machine Fragment: Unknown Spectrum', ['physics.waves', 'chemistry.elements'], 22, 'An ancient light source produces spectral lines that match no known element.', [_s('measure', 'Record the emission spectrum of the ancient light source using the spectrometer.', 'Document the wavelength of each spectral line precisely.'), _s('compare', 'Compare each spectral line to the known emission spectra of all elements.', 'Check hydrogen, helium, and transition metals for matches.'), _s('solve', 'Calculate the energy transitions implied by the unknown spectral lines.', 'Energy = h times c / wavelength for each line.'), _s('pattern', 'Look for a mathematical pattern in the energy levels that might identify the source.', 'Known elements follow predictable energy level patterns.')], True),
