# TRADING POST — Economics, Math hub
# ============================================================================
def trading_post():
    Q = []
    Q.append(_q('supply-demand', 'Supply and Demand Dynamics', ['economics.supply-demand', 'math.equations'], 22, 'The Trading Post needs supply and demand analysis to set fair prices for goods.', [_s('observe', 'Survey how much of three goods traders want to buy at different price levels.', 'At lower prices, demand increases; at higher prices, it decreases.'), _s('build', 'Plot supply and demand curves on a graph for each good.', 'Price on y-axis, quantity on x-axis.'), _s('solve', 'Find the equilibrium price where supply equals demand for each good.', 'Equilibrium is where the two curves cross.'), _s('predict', 'Predict what happens to equilibrium price if supply suddenly decreases.', 'Less supply shifts the supply curve left, raising the price.')]))
    Q.append(_q('profit-margin', 'Profit Margin Analysis', ['economics.entrepreneurship', 'math.percentages'], 20, 'Trading Post merchants need to calculate profit margins to stay in business.', [_s('measure', 'Record the cost price and selling price of ten different goods.', 'Cost is what the merchant paid; selling price is what customers pay.'), _s('solve', 'Calculate profit margin for each: (selling - cost) / selling times 100.', 'Profit margin is expressed as a percentage of selling price.'), _s('sort', 'Rank goods by profit margin from highest to lowest.', 'Higher margin goods earn more per sale.'), _s('optimize', 'Determine the optimal pricing strategy that balances margin with sales volume.', 'Sometimes a lower margin with more sales earns more total profit.')]))
    Q.append(_q('compound-interest', 'Compound Interest Growth', ['economics.banking', 'math.equations'], 22, 'The Trading Post bank offers savings accounts with compound interest that needs calculation.', [_s('solve', 'Calculate simple interest on a 1000-coin deposit at 5 percent for 3 years.', 'Simple interest = principal times rate times time.'), _s('solve', 'Calculate compound interest on the same deposit compounded annually.', 'A = P(1 + r)^t where P is principal, r is rate, t is time in years.'), _s('compare', 'Compare the final amounts from simple vs compound interest over 10 years.', 'Compound interest earns more because interest earns interest.'), _s('predict', 'Predict how long it takes for the deposit to double at 5 percent compound interest.', 'Use the Rule of 72: years to double is approximately 72 / interest rate.')]))
