    Q.append(_q('machine-code-logic', 'Machine Fragment: Logic Crystal', ['cs.conditionals', 'math.equations'], 22, 'A crystal processes logical operations when light patterns are shone through it.', [_s('experiment', 'Shine different light patterns through the crystal and record the outputs.', 'Try single beams and combinations of beams.'), _s('decode', 'Map the input-output relationship to identify which logic operations the crystal performs.', 'Compare outputs to AND, OR, NOT, and XOR truth tables.'), _s('code', 'Replicate the crystal logic operations in a modern program.', 'Implement each discovered logic gate as a function.'), _s('compare', 'Compare the crystal processing speed to modern electronic logic gates.', 'Time how fast the crystal responds compared to modern circuits.')], True))
