    Q.append(_q('machine-code-encrypt', 'Machine Fragment: Cipher Wheel', ['cs.algorithms', 'math.patterns'], 22, 'An ancient cipher wheel encrypts and decrypts messages using a method more complex than any known historical cipher.', [_s('experiment', 'Encode a test message using the cipher wheel and record the output.', 'Turn the wheel settings and write down the encoded text.'), _s('decode', 'Try to crack the cipher by encoding the same message with different wheel settings.', 'Look for patterns in how the settings affect the output.'), _s('compare', 'Compare the cipher complexity to Caesar, Vigenere, and modern encryption.', 'Analyze the key space and substitution pattern.'), _s('code', 'Implement a digital version of the cipher wheel encoding algorithm.', 'Translate the mechanical process into code step by step.')], True))
