    Q.append(_q('immune-response', 'Immune System Defense', ['biology.cell-biology', 'biology.genetics'], 22, 'The Sanctuary studies immune responses to develop better protective treatments.', [_s('observe', 'Examine how white blood cells respond to a simulated infection.', 'Watch phagocytes engulf pathogens and antibodies attach to invaders.'), _s('sequence', 'Map the immune response stages: detection, response, memory.', 'The body first detects the pathogen, then mounts a response, then remembers it.'), _s('compare', 'Compare the innate immune response (general) to the adaptive response (specific).', 'Innate is fast but general; adaptive is slower but targets specific pathogens.'), _s('predict', 'Predict why a second exposure to the same pathogen causes a faster immune response.', 'Memory cells from the first exposure recognize the pathogen immediately.')]))
