    Q.append(_q('plant-structure', 'Plant Anatomy Study', ['biology.cell-biology', 'biology.photosynthesis'], 20, 'Medicinal plant structures must be documented to identify the most potent parts.', [_s('observe', 'Examine cross-sections of root, stem, and leaf under magnification.', 'Note the different cell types and arrangements in each organ.'), _s('compare', 'Compare the vascular tissue arrangement in monocot vs dicot plants.', 'Monocots have scattered vascular bundles; dicots have them in a ring.'), _s('match', 'Match each plant structure to its function: roots absorb, stems transport, leaves photosynthesize.', 'Each organ is specialized for specific functions.'), _s('predict', 'Predict which part of a new medicinal plant would contain the most active compounds.', 'Consider where the plant stores defensive chemicals.')]))
