    Q.append(_q('human-respiratory', 'Respiratory System Function', ['biology.cell-biology', 'chemistry.reactions'], 20, 'Understanding gas exchange in the lungs helps the Sanctuary treat breathing ailments.', [_s('observe', 'Examine the respiratory system model showing airways, lungs, and alveoli.', 'Note how the airways branch into smaller and smaller passages.'), _s('measure', 'Calculate the total surface area of the lung alveoli.', 'Millions of tiny alveoli provide a huge surface for gas exchange.'), _s('compare', 'Compare the oxygen and carbon dioxide content of inhaled vs exhaled air.', 'Inhaled air is about 21% oxygen; exhaled is about 16% oxygen.'), _s('solve', 'Calculate the volume of oxygen absorbed per breath using the concentration difference.', 'Volume absorbed = breath volume times (inhaled% - exhaled%) concentration.')]))
    Q.append(_q('nutrition-energy', 'Nutrition and Energy', ['biology.cell-biology', 'math.equations'], 20, 'Sanctuary patients need proper nutrition, requiring understanding of food energy content.', [_s('measure', 'Determine the energy content of three food types using the calorimeter.', 'Burn a measured food sample and record the temperature rise in water.'), _s('solve', 'Calculate calories using q = mass of water times specific heat times temperature change.', 'Convert joules to calories by dividing by 4.184.'), _s('compare', 'Compare energy per gram across carbohydrates, proteins, and fats.', 'Fats contain about 9 cal/g; carbs and protein contain about 4 cal/g.'), _s('design', 'Design a balanced meal plan meeting a target daily calorie intake.', 'Combine foods to reach the target while providing all macronutrients.')]))
    Q.append(_q('ph-body', 'Body pH Balance', ['chemistry.ph-acids-bases', 'biology.cell-biology'], 20, 'The Sanctuary monitors body fluid pH to diagnose and treat imbalances.', [_s('measure', 'Test the pH of six different body fluid samples from the lab.', 'Use the pH indicator for each sample.'), _s('sort', 'Arrange the fluids from most acidic to most basic on the pH scale.', 'Stomach acid is very acidic; blood is slightly basic.'), _s('predict', 'Predict the health implications of blood pH shifting outside the 7.35-7.45 range.', 'Even small pH changes can affect enzyme function and cell processes.'), _s('solve', 'Calculate the hydrogen ion concentration from a given pH value.', 'pH = -log[H+], so [H+] = 10^(-pH).')]))
    Q.append(_q('dosage-calculations', 'Medicine Dosage Ratios', ['math.ratios', 'math.proportions'], 18, 'Sanctuary medicines must be dosed precisely based on patient weight and condition.', [_s('solve', 'Calculate the correct dosage for a 60 kg patient at a rate of 5 mg per kg.', 'Dosage = weight times rate = 60 times 5 = 300 mg.'), _s('solve', 'Convert the dosage from mg to mL using solution concentration of 25 mg per mL.', 'Volume = dosage / concentration = 300 / 25 = 12 mL.'), _s('solve', 'Calculate dosages for patients of different weights and ages.', 'Apply the same rate formula with different weight values.'), _s('predict', 'Determine if a calculated dose exceeds the maximum safe daily limit.', 'Compare the calculated dose to the published maximum.')]))
    Q.append(_q('statistics-patients', 'Patient Recovery Statistics', ['math.statistics', 'biology.cell-biology'], 18, 'Patient recovery data needs statistical analysis to evaluate treatment effectiveness.', [_s('collect', 'Record recovery times for 20 patients receiving the same treatment.', 'Note the number of days from treatment to full recovery for each patient.'), _s('solve', 'Calculate the mean, median, and range of recovery times.', 'Mean = sum / count; median = middle value when sorted; range = max - min.'), _s('compare', 'Compare recovery statistics between two different treatments.', 'The treatment with lower mean and less variation is more reliable.'), _s('predict', 'Estimate the likely recovery time for a new patient on the better treatment.', 'Use the mean as the best estimate with the range as uncertainty.')]))
