    Q.append(_q('percentage-composition-herb', 'Herbal Compound Analysis', ['math.percentages', 'chemistry.compounds'], 18, 'Medicinal herbs contain active compounds whose percentages must be measured.', [_s('measure', 'Extract and weigh the active compound from a known mass of dried herb.', 'Use the extraction procedure to isolate the compound.'), _s('solve', 'Calculate the percentage of active compound in the herb.', 'Percentage = (compound mass / total herb mass) times 100.'), _s('compare', 'Compare potency across herbs from different growing conditions.', 'More sunlight or specific soil conditions may increase active compound percentage.'), _s('predict', 'Predict the amount of herb needed to obtain 10 grams of active compound.', 'Required herb mass = desired compound mass / (percentage/100).')]))
