    Q.append(_q('coding-dosage-calc', 'Dosage Calculator Program', ['cs.functions', 'math.equations'], 20, 'A dosage calculation program needs to prevent medication errors.', [_s('code', 'Write a function that calculates dosage from patient weight and dosage rate.', 'Dosage = weight_kg times rate_mg_per_kg.'), _s('code', 'Add input validation that rejects unreasonable values.', 'Reject negative weights, zero rates, and doses above the maximum safe limit.'), _s('code', 'Write a function that converts between dosage units: mg to mL, g to mg.', 'Each conversion uses a specific factor.'), _s('experiment', 'Test with normal cases, edge cases, and intentionally dangerous doses.', 'Verify correct calculations and proper rejection of unsafe values.')]))
    # Story quests (7)
