    Q.append(_q('machine-heal-analyzer', 'Machine Fragment: Compound Analyzer', ['chemistry.compounds', 'biology.cell-biology'], 22, 'An ancient device identifies the complete chemical composition of any biological sample instantly.', [_s('experiment', 'Feed known compounds into the analyzer and check if it identifies them correctly.', 'Start with simple, well-characterized samples.'), _s('measure', 'Determine the accuracy and precision of the analyzer identifications.', 'Compare analyzer results to known compositions.'), _s('compare', 'Compare the analysis speed and accuracy to modern spectrometry.', 'Modern analysis of complex samples takes hours; this takes seconds.'), _s('observe', 'Analyze an unknown plant sample and verify the results using traditional methods.', 'Cross-check the instant analysis against standard lab procedures.')], True))
