    Q.append(_q('machine-heal-seed', 'Machine Fragment: Enhanced Seeds', ['biology.genetics', 'biology.photosynthesis'], 22, 'Seeds from an ancient machine grow into plants with enhanced medicinal properties.', [_s('experiment', 'Grow ancient and modern versions of the same plant species side by side.', 'Control all growing conditions to isolate genetic differences.'), _s('measure', 'Compare active compound concentrations in ancient vs modern plants.', 'Extract and measure the medicinal compound from each.'), _s('compare', 'Analyze whether the enhanced plants have visible structural differences.', 'Compare leaf, root, and stem anatomy under magnification.'), _s('predict', 'Hypothesize what genetic modifications could produce the observed enhancements.', 'Consider which genes control the production of medicinal compounds.')], True))
