# Remaining 15 biomes follow a compact pattern using _make_biome_quests

def farm():
    return _make_biome_quests('farm', [
        ('plant-growth', 'Crop Growth Variables', ['biology.photosynthesis', 'math.equations'], 20, 'Farm crops grow at rates depending on sunlight, water, and soil that need measurement.', [_s('experiment', 'Grow identical plants under three different light conditions and track growth.', 'Control all variables except light exposure.'), _s('measure', 'Record height weekly for four weeks under each condition.', 'Measure from soil to highest point each week.'), _s('solve', 'Calculate the growth rate in cm per week for each condition.', 'Rate = (final - initial height) / weeks.'), _s('predict', 'Predict which condition will produce the tallest plants at harvest time.', 'Extend the growth rate trends forward.')]),
        ('soil-ph', 'Soil pH and Crop Yield', ['chemistry.ph-acids-bases', 'biology.ecosystems'], 20, 'Different crops need different soil pH levels for optimal growth.', [_s('measure', 'Test the pH of soil from five different Farm plots.', 'Use the pH testing kit on each sample.'), _s('compare', 'Compare each plot pH to the optimal range for corn, beans, and potatoes.', 'Corn prefers 6.0-6.8; beans prefer 6.0-7.0; potatoes prefer 5.0-6.0.'), _s('predict', 'Predict which crop will grow best in each plot based on pH match.', 'Crops in their optimal pH range produce higher yields.'), _s('design', 'Plan soil amendments to adjust pH for the desired crop in each plot.', 'Adding lime raises pH; adding sulfur lowers it.')]),
        ('punnett-breeding', 'Selective Breeding Program', ['biology.genetics', 'math.probability'], 22, 'Farm animals need selective breeding using genetics to improve traits.', [_s('observe', 'Record the phenotype traits of parent animals for disease resistance.', 'Note which parents show the desired trait and which do not.'), _s('solve', 'Determine parent genotypes and create Punnett squares for crosses.', 'If the trait is recessive, carrier parents are heterozygous.'), _s('predict', 'Calculate the probability of offspring expressing the desired trait.', 'Count favorable outcomes in the Punnett square.'), _s('design', 'Plan a multi-generation breeding program to increase trait frequency.', 'Select only trait-expressing offspring for the next generation of breeding.')]),
        ('ecosystem-farm', 'Farm Ecosystem Balance', ['biology.ecosystems', 'biology.ecology'], 20, 'The Farm ecosystem must balance pest control with beneficial organism protection.', [_s('observe', 'Survey all organism types on the Farm: crops, pests, predators, pollinators.', 'Catalog every species and estimate their population.'), _s('build', 'Construct a food web showing all feeding relationships on the Farm.', 'Draw arrows from food source to consumer.'), _s('predict', 'Predict what happens if a pesticide eliminates all insects including pollinators.', 'Removing pollinators would dramatically reduce crop yields.'), _s('design', 'Design an integrated pest management plan that protects beneficial organisms.', 'Use targeted methods that control pests without harming pollinators.')]),
        ('fertilizer-chem', 'Fertilizer Chemistry', ['chemistry.compounds', 'math.ratios'], 20, 'Farm fertilizers need correct NPK ratios calculated for each crop type.', [_s('decode', 'Interpret the N-P-K numbers on fertilizer bags: nitrogen, phosphorus, potassium.', 'A 10-5-5 fertilizer is 10% nitrogen, 5% phosphorus, 5% potassium.'), _s('solve', 'Calculate how much fertilizer to apply per hectare for a target nitrogen amount.', 'If you need 100 kg N per hectare with 10% N fertilizer, you need 1000 kg fertilizer.'), _s('compare', 'Compare organic vs synthetic fertilizers in terms of NPK ratios and cost.', 'Organic fertilizers typically have lower NPK but improve soil structure.'), _s('predict', 'Predict crop yield improvement from optimal vs suboptimal fertilization.', 'Research shows optimal fertilization can increase yields by 30-50%.')]),
        ('water-irrigation', 'Irrigation Efficiency', ['engineering.design-process', 'math.percentages'], 22, 'The Farm irrigation system wastes water and needs efficiency analysis.', [_s('measure', 'Measure water input from the source and water reaching the crop roots.', 'Record total water pumped and water absorbed by soil near roots.'), _s('solve', 'Calculate irrigation efficiency as useful water divided by total water times 100.', 'Efficiency percentage shows how much water is actually used by crops.'), _s('compare', 'Compare drip irrigation, sprinkler, and flood irrigation efficiency.', 'Drip is typically 90%+ efficient; flood may be only 50%.'), _s('design', 'Design an improved irrigation layout that increases efficiency by 20%.', 'Target the water delivery closer to the plant root zones.')]),
        ('area-yield', 'Field Area and Yield', ['math.area-volume', 'economics.entrepreneurship'], 18, 'Farm field areas must be calculated to predict total crop yields.', [_s('measure', 'Measure the dimensions of four irregularly shaped farm fields.', 'Break each field into rectangles and triangles for measurement.'), _s('solve', 'Calculate the area of each field by summing component shapes.', 'Total area = sum of all component rectangles and triangles.'), _s('solve', 'Calculate expected yield for each field using crop yield per hectare.', 'Total yield = area in hectares times yield per hectare.'), _s('predict', 'Predict total Farm revenue from the yield multiplied by market price.', 'Revenue = total yield times price per unit.')]),
        ('economics-farm', 'Farm Economics', ['economics.entrepreneurship', 'math.equations'], 22, 'Farm profitability depends on cost management and pricing decisions.', [_s('collect', 'List all Farm expenses: seeds, fertilizer, equipment, labor, water.', 'Record the cost of each category for the growing season.'), _s('solve', 'Calculate total cost of production and cost per unit of crop.', 'Cost per unit = total costs / total units produced.'), _s('solve', 'Calculate the break-even price: the minimum selling price to cover costs.', 'Break-even price = total costs / total units.'), _s('predict', 'Predict profit or loss at three different market price scenarios.', 'Profit = (price - cost per unit) times quantity.')]),
        ('statistics-harvest', 'Harvest Statistics', ['math.statistics', 'biology.ecology'], 18, 'Harvest data from multiple seasons needs statistical analysis for planning.', [_s('collect', 'Compile yield data from the past five growing seasons.', 'Record the total harvest for each year.'), _s('solve', 'Calculate mean, median, and standard deviation of the yield data.', 'These statistics describe the typical yield and its variability.'), _s('predict', 'Estimate the yield range for next season using mean plus/minus one standard deviation.', 'About 68% of seasons should fall within this range.'), _s('compare', 'Correlate yield data with rainfall data to identify the key factor.', 'Years with more rain should show different yield patterns.')]),
        ('proportion-feed', 'Animal Feed Ratios', ['math.proportions', 'biology.ecosystems'], 18, 'Animal feed must be mixed in precise proportions for optimal nutrition.', [_s('solve', 'Mix a 60:30:10 ratio of grain, protein supplement, and minerals for 100 kg of feed.', 'Calculate 60 kg grain, 30 kg protein, 10 kg minerals.'), _s('solve', 'Scale the recipe from 100 kg to 350 kg while maintaining the ratio.', 'Multiply each component by 3.5.'), _s('measure', 'Weigh each component and verify the ratios before mixing.', 'Use the farm scale to confirm each amount.'), _s('predict', 'Calculate how many days the 350 kg batch will feed 20 animals at 2 kg per day each.', 'Days = total feed / (number of animals times daily consumption).')]),
        ('percentage-germination', 'Seed Germination Rates', ['math.percentages', 'biology.cell-biology'], 18, 'Seed batches must be tested for germination rate before large-scale planting.', [_s('experiment', 'Plant 100 seeds from a batch and count how many germinate in 10 days.', 'Keep conditions consistent: same soil, water, and temperature.'), _s('solve', 'Calculate the germination rate as a percentage.', 'Rate = germinated seeds / total seeds times 100.'), _s('predict', 'Predict how many seeds to plant to get 500 seedlings at the measured germination rate.', 'Seeds needed = desired plants / (germination rate / 100).'), _s('compare', 'Compare germination rates of seeds stored at different temperatures.', 'Proper storage conditions maintain higher germination rates.')]),
        ('linear-growth-crop', 'Crop Growth Modeling', ['math.linear-functions', 'biology.photosynthesis'], 20, 'Crop height growth follows linear patterns during the vegetative phase.', [_s('measure', 'Record crop heights weekly for 8 weeks during the growing season.', 'Measure the same marked plants each week.'), _s('solve', 'Plot height vs week and determine the growth rate from the slope.', 'Slope = change in height / change in weeks.'), _s('solve', 'Write the linear equation for growth: h = rate times week + initial height.', 'Find the y-intercept from the first measurement.'), _s('predict', 'Predict the crop height at harvest time using the growth equation.', 'Substitute the harvest week number into the equation.')]),
        ('coding-crop-tracker', 'Crop Tracking System', ['cs.data-structures', 'cs.functions'], 20, 'The Farm needs a digital system to track crop plantings, care, and harvests.', [_s('code', 'Design a data structure for crop records: type, plot, planting date, expected harvest.', 'Each record stores information about one crop planting.'), _s('code', 'Write functions to add plantings, log care activities, and record harvest data.', 'Each function modifies the appropriate fields in the record.'), _s('code', 'Create a report function summarizing active plantings and upcoming harvests.', 'Filter records by status and format them for display.'), _s('experiment', 'Test the system with a full season of simulated farm operations.', 'Add, update, and report through planting, growing, and harvest phases.')]),
        ('coding-weather', 'Weather Data Analyzer', ['cs.functions', 'math.statistics'], 20, 'Farm weather data needs automated analysis for planting decisions.', [_s('code', 'Write a function that reads temperature data and calculates daily averages.', 'Average = (max + min) / 2 for each day.'), _s('code', 'Write a function that counts frost-free days in a growing season.', 'Count days where the minimum temperature stays above freezing.'), _s('code', 'Create a function that determines the last spring frost and first fall frost.', 'Scan from both ends of the year toward the middle.'), _s('experiment', 'Run the analyzer on three years of weather data and compare results.', 'Verify the frost dates match known historical records.')]),
        ('equation-profit', 'Profit Equation Modeling', ['math.equations', 'economics.entrepreneurship'], 18, 'Farm profit follows an equation that depends on yield, price, and costs.', [_s('solve', 'Write the profit equation: P = (price times yield) minus total costs.', 'This gives profit as a function of the key variables.'), _s('solve', 'Calculate profit at three different yield levels.', 'Substitute each yield value into the equation.'), _s('solve', 'Find the break-even yield: the minimum yield needed to cover costs.', 'Set P = 0 and solve for yield.'), _s('predict', 'Predict the price increase needed to maintain profit if yield drops 20%.', 'Adjust both variables in the equation and solve for the new price.')]),
        ('probability-weather', 'Weather Risk Probability', ['math.probability', 'biology.ecosystems'], 18, 'Farm planning requires probability estimates for weather events.', [_s('collect', 'Review 20 years of rainfall data during planting season.', 'Count years with below-average, average, and above-average rainfall.'), _s('solve', 'Calculate the probability of below-average rainfall during planting.', 'Probability = years with low rainfall / total years.'), _s('predict', 'Calculate the probability of two consecutive drought years.', 'If independent, multiply individual probabilities.'), _s('solve', 'Determine the expected financial impact of drought based on probability and losses.', 'Expected loss = probability times loss amount.')]),
        ('ratio-crop-rotation', 'Crop Rotation Ratios', ['math.ratios', 'biology.ecosystems'], 18, 'Crop rotation must follow specific ratios of crop types for soil health.', [_s('solve', 'Design a rotation with a 2:1:1 ratio of grain, legume, and root crops.', 'In a 4-field system: 2 fields grain, 1 legume, 1 root.'), _s('solve', 'Calculate the area devoted to each crop type given 40 hectares total.', '2:1:1 ratio means 20 ha grain, 10 ha legume, 10 ha root.'), _s('predict', 'Predict how the legume phase restores nitrogen for the following grain phase.', 'Legumes fix atmospheric nitrogen into the soil.'), _s('compare', 'Compare soil nutrient levels after rotation vs monoculture.', 'Rotation maintains soil health better than planting the same crop every year.')]),
        ('coordinate-fields', 'Field Coordinate Mapping', ['math.coordinate-geometry', 'engineering.design-process'], 18, 'Farm fields need coordinate mapping for precision agriculture applications.', [_s('design', 'Set up a coordinate grid over the Farm with the barn as origin.', 'Use north-south and east-west as axis directions.'), _s('place', 'Plot the boundaries and features of each field on the coordinate system.', 'Mark corners, water sources, and access roads.'), _s('solve', 'Calculate field areas from the coordinate points.', 'Use the coordinate geometry area formula for irregular polygons.'), _s('solve', 'Calculate the optimal location for a new irrigation pump between two fields.', 'The midpoint between field centers minimizes total pipe length.')]),
        ('scientific-notation-farm', 'Farm-Scale Numbers', ['math.scientific-notation', 'biology.ecology'], 18, 'Farm operations deal with very large and very small numbers needing scientific notation.', [_s('transform', 'Express the Farm total water usage of 5,400,000 liters in scientific notation.', '5,400,000 = 5.4 x 10^6 liters.'), _s('solve', 'Calculate the number of seeds in a 50 kg bag given 500 seeds per gram.', '50 kg = 50,000 g; total seeds = 25,000,000 = 2.5 x 10^7.'), _s('solve', 'Calculate the mass of a single grain of soil at 0.000065 grams in scientific notation.', '0.000065 = 6.5 x 10^-5 grams.'), _s('compare', 'Express farm-scale quantities alongside microscopic quantities to understand scale.', 'Farm area in square meters vs bacterial cell area in square micrometers.')]),
        ('exponents-doubling', 'Population Doubling', ['math.exponents', 'biology.ecology'], 18, 'Pest populations double at regular intervals and need exponential modeling.', [_s('observe', 'Track aphid population on a test plant over 10 days.', 'Count the aphids every two days.'), _s('solve', 'Express the growth pattern using exponents: population = initial times 2^n.', 'If the population doubles every 2 days, n = days/2.'), _s('solve', 'Calculate the population after 20 days using the exponential formula.', 'n = 10 doublings; population = initial times 2^10 = initial times 1024.'), _s('predict', 'Predict the day when population exceeds the damage threshold of 10,000 aphids.', 'Solve 2^n times initial = 10,000 for n.')]),
    ], [
        ('machine-farm-planter', 'Machine Fragment: Autonomous Planter', ['engineering.mechanisms', 'biology.photosynthesis'], 22, 'An ancient planting device places seeds at mathematically optimal spacing no human could match.', [_s('observe', 'Measure the spacing pattern the device uses for planting.', 'Note both row spacing and within-row spacing.'), _s('measure', 'Compare the planting pattern to hexagonal close-packing optimization.', 'Calculate the area each plant receives in the ancient vs standard pattern.'), _s('compare', 'Compare crop yields from the ancient spacing vs traditional row planting.', 'Measure yield per unit area for both approaches.'), _s('solve', 'Calculate the mathematical optimization principle behind the ancient spacing.', 'Determine if the pattern maximizes sunlight access, root space, or both.')]),
        ('machine-farm-water', 'Machine Fragment: Water Finder', ['physics.waves', 'biology.ecosystems'], 22, 'An ancient device detects underground water with precision modern technology cannot match.', [_s('experiment', 'Test the device at locations with known water table depths.', 'Compare device readings to actual measured depths.'), _s('measure', 'Map the accuracy of water detection across different soil types.', 'Record accuracy at each test site.'), _s('compare', 'Compare detection accuracy to modern ground-penetrating radar.', 'Note which method better identifies water depth and volume.'), _s('predict', 'Use the device to find optimal well placement for a new field.', 'The device should indicate the shallowest water table location.')]),
        ('machine-farm-soil', 'Machine Fragment: Soil Rejuvenator', ['chemistry.compounds', 'biology.ecosystems'], 22, 'An ancient device restores depleted soil to peak fertility in days rather than seasons.', [_s('measure', 'Test soil fertility before and after the device treatment.', 'Measure nitrogen, phosphorus, potassium, and organic matter.'), _s('experiment', 'Grow identical crops in treated and untreated soil side by side.', 'Control all variables except the soil treatment.'), _s('compare', 'Compare the rejuvenation to the best modern soil amendments.', 'Time and effectiveness comparisons.'), _s('observe', 'Examine the treated soil for any visible biological or chemical changes.', 'Look for differences in color, texture, and organism activity.')]),
        ('machine-farm-harvest', 'Machine Fragment: Yield Predictor', ['math.statistics', 'biology.photosynthesis'], 22, 'An ancient device predicts exact harvest yields months before harvest with remarkable accuracy.', [_s('observe', 'Record the device predictions at planting time for each field.', 'Note the predicted yield and any conditions mentioned.'), _s('measure', 'Compare predictions to actual yields at harvest time.', 'Calculate the prediction error for each field.'), _s('solve', 'Analyze what variables the device might use to make accurate predictions.', 'Consider soil, weather, genetics, and planting density.'), _s('compare', 'Compare prediction accuracy to modern crop forecasting models.', 'Modern models are typically accurate to within 10-15%.')]),
        ('machine-farm-pest', 'Machine Fragment: Pest Barrier', ['biology.ecology', 'physics.waves'], 22, 'An ancient device creates an invisible barrier that repels crop pests without harming other organisms.', [_s('observe', 'Document which organisms are repelled and which pass through unaffected.', 'Test with pests, pollinators, and neutral organisms.'), _s('measure', 'Determine the range and boundaries of the pest barrier effect.', 'Walk test organisms toward the device at different distances.'), _s('experiment', 'Test whether the barrier works selectively by pest type.', 'Try different pest species and record which are repelled.'), _s('compare', 'Compare the barrier effectiveness to modern integrated pest management.', 'Calculate crop loss reduction with vs without the barrier.')]),
        ('machine-farm-weather', 'Machine Fragment: Micro-Climate Generator', ['physics.thermal-energy', 'biology.photosynthesis'], 22, 'An ancient device creates a stable micro-climate bubble over a small area regardless of external weather.', [_s('measure', 'Record temperature, humidity, and wind inside vs outside the bubble.', 'Place sensors at both locations and compare.'), _s('experiment', 'Test whether the bubble protects crops during simulated frost and heat events.', 'Create extreme conditions outside and measure inside conditions.'), _s('compare', 'Compare crop growth inside the bubble to identical crops outside.', 'Track growth rate, health, and yield for both groups.'), _s('solve', 'Calculate the energy required to maintain the observed temperature difference.', 'Use thermal energy equations to estimate the power needed.')]),
        ('machine-farm-growth', 'Machine Fragment: Growth Harmonizer', ['biology.cell-biology', 'physics.waves'], 22, 'An ancient device causes all plants within range to grow at precisely the same rate.', [_s('observe', 'Document growth patterns of multiple plant species within the device range.', 'Compare fast-growing and slow-growing species.'), _s('measure', 'Measure growth rates for each species with and without the device active.', 'Calculate how much each species speeds up or slows down.'), _s('compare', 'Compare the harmonized growth rate to each species natural rate.', 'Determine if the harmonized rate is an average or a fixed value.'), _s('experiment', 'Test whether the device affects plant quality or just growth speed.', 'Compare nutritional content and structural strength.')]),
    ])


