def _4step(t1,i1,h1,t2,i2,h2,t3,i3,h3,t4,i4,h4):
    return [_s(t1,i1,h1),_s(t2,i2,h2),_s(t3,i3,h3),_s(t4,i4,h4)]

def laboratory():
    S = [
        ('reaction-types', 'Classifying Chemical Reactions', ['chemistry.reactions', 'chemistry.balancing-equations'], 22, 'Lab reactions must be classified by type to predict products.', _4step('observe','Run five reactions and record reactants, products, and observable changes.','Note color changes, gas bubbles, temperature shifts, and precipitates.','sort','Classify each reaction: synthesis, decomposition, single replacement, or double replacement.','Synthesis: A+B=AB; Decomposition: AB=A+B.','balance','Write and balance the chemical equation for each reaction.','Same number of each atom on both sides.','predict','Predict products of a new reaction from its type and reactants.','Use the pattern of the identified reaction type.')),
        ('limiting-reagent', 'Limiting Reagent Determination', ['chemistry.stoichiometry', 'math.ratios'], 22, 'Lab reactions stop when one reagent runs out and determining which one limits the reaction is critical.', _4step('solve','Calculate the moles of each reactant from their masses using molar mass.','Moles = mass in grams / molar mass.','solve','Use the balanced equation to find the mole ratio required between reactants.','Coefficients in the equation give the ratio.','compare','Determine which reactant runs out first based on the available moles and ratio.','The limiting reagent is the one that would run out first.','predict','Calculate the theoretical yield of product based on the limiting reagent.','Convert limiting reagent moles to product moles using the ratio.')),
        ('gas-law-combined', 'Combined Gas Law', ['chemistry.gas-laws', 'math.equations'], 22, 'Gas experiments require the combined gas law when pressure, volume, and temperature all change.', _4step('measure','Record the pressure, volume, and temperature of a gas sample.','Use the manometer, syringe, and thermometer.','solve','Apply P1V1/T1 = P2V2/T2 to predict the new volume after changes.','Temperatures must be in Kelvin for this formula.','experiment','Change two variables simultaneously and measure the third.','Vary pressure and temperature, then measure volume.','predict','Predict the gas conditions at a different temperature and pressure.','Substitute known values and solve for the unknown.')),
        ('spectroscopy-id', 'Spectroscopic Identification', ['physics.optics', 'chemistry.elements'], 22, 'Unknown elements produce unique spectral signatures that identify them.', _4step('experiment','Heat samples of unknown elements and observe the flame color.','Each element produces a characteristic flame color.','measure','Record the emission spectrum of each unknown using the spectrometer.','Note the wavelengths of each bright line in the spectrum.','match','Match the spectral lines to known element reference spectra.','Compare your measurements to the reference database.','decode','Identify all unknown samples from their spectral fingerprints.','Each element has a unique set of spectral lines.')),
        ('titration-basics', 'Acid-Base Titration', ['chemistry.ph-acids-bases', 'math.equations'], 22, 'The concentration of an unknown acid must be determined by titration with a known base.', _4step('measure','Set up a titration with a known base and indicator in the unknown acid.','Add the base slowly from a burette and watch for color change.','measure','Record the exact volume of base needed to reach the endpoint.','The endpoint is when the indicator changes color permanently.','solve','Calculate the unknown acid concentration using C1V1 = C2V2.','Rearrange to find the unknown concentration.','experiment','Repeat the titration three times and average the results.','Multiple trials improve accuracy and reliability.')),
        ('solubility-curves', 'Solubility Curve Analysis', ['chemistry.solutions', 'math.equations'], 20, 'The Lab needs solubility curves to predict how much solute dissolves at each temperature.', _4step('experiment','Dissolve increasing amounts of salt in water at four different temperatures.','Heat the water to each target temperature before adding solute.','measure','Record the maximum amount that dissolves at each temperature.','Add solute until no more dissolves and record the amount.','solve','Plot temperature vs solubility to create the solubility curve.','Place temperature on x-axis and grams dissolved per 100 mL on y-axis.','predict','Predict the solubility at a temperature not tested using the curve.','Interpolate between the plotted data points.')),
        ('conservation-mass-lab', 'Mass Conservation Verification', ['chemistry.reactions', 'math.equations'], 20, 'Every reaction must conserve mass, which needs experimental verification.', _4step('measure','Weigh reactants in a sealed container before the reaction.','Include the container in the total mass.','experiment','Run the reaction in the sealed container and observe changes.','Note any gas production, color change, or energy release.','measure','Weigh the sealed container after the reaction.','The mass should be identical to the initial measurement.','solve','Repeat in an open container and calculate the mass of gas escaping.','Mass of gas = initial total mass - final mass in open container.')),
        ('precision-accuracy', 'Precision vs Accuracy', ['math.statistics', 'chemistry.solutions'], 20, 'Lab measurements must be both precise and accurate, and the difference needs demonstration.', _4step('experiment','Measure the same liquid volume ten times with three different instruments.','Use a beaker, graduated cylinder, and burette.','solve','Calculate the mean and standard deviation for each instrument.','Smaller standard deviation means higher precision.','compare','Determine which instrument is most precise and which is most accurate.','Precision is about consistency; accuracy is about closeness to the true value.','predict','Predict which instrument gives the most reliable single measurement.','The most precise and accurate instrument gives the best single reading.')),
        ('molar-mass-calc', 'Molar Mass Calculations', ['chemistry.compounds', 'math.equations'], 20, 'Lab compound quantities require molar mass calculations for proper measurement.', _4step('solve','Calculate the molar mass of water (H2O) from atomic masses.','H = 1.008, O = 15.999; H2O = 2(1.008) + 15.999 = 18.015 g/mol.','solve','Calculate the molar mass of glucose (C6H12O6).','C = 12.011; sum all atoms: 6(12.011) + 12(1.008) + 6(15.999).','solve','Convert 50 grams of NaCl to moles using molar mass.','Moles = mass / molar mass.','experiment','Weigh out exactly 0.5 moles of three different compounds.','Mass to weigh = 0.5 times the molar mass.')),
        ('density-lab', 'Density Measurement Lab', ['physics.density', 'math.equations'], 18, 'Unknown liquids need density measurement for identification.', _4step('measure','Measure the mass and volume of five unknown liquids.','Tare the container before adding each liquid.','solve','Calculate density for each liquid: density = mass / volume.','Use consistent units like g/mL.','match','Match each density to a known liquid in the reference table.','Each liquid has a characteristic density.','experiment','Test your identification by checking another property of each liquid.','Boiling point or refractive index can confirm identification.')),
        ('unit-conversion-lab', 'Lab Unit Conversions', ['math.equations', 'math.proportions'], 18, 'Lab protocols use different unit systems that need accurate conversion.', _4step('solve','Convert between mL, L, and cubic centimeters for volume.','1 mL = 1 cc; 1000 mL = 1 L.','solve','Convert between grams, kilograms, and milligrams for mass.','1 kg = 1000 g; 1 g = 1000 mg.','solve','Convert temperature between Celsius and Kelvin.','K = C + 273.15.','experiment','Verify conversions by measuring the same quantity in different units.','The converted values should describe the same physical amount.')),
        ('graphing-lab', 'Lab Data Graphing', ['math.coordinate-geometry', 'math.statistics'], 20, 'Experimental data must be graphed to reveal relationships between variables.', _4step('collect','Gather data pairs from a temperature-solubility experiment.','Record both variables for each trial.','solve','Plot the data on a coordinate graph with proper axis labels and scales.','Independent variable on x-axis, dependent on y-axis.','solve','Determine if the relationship is linear, exponential, or inverse.','Check if points form a straight line, curve up, or curve down.','solve','Calculate the slope if linear or identify the curve equation if not.','Use two points for slope; compare to known curve shapes.')),
        ('equation-chemical', 'Chemical Equation Modeling', ['math.equations', 'chemistry.balancing-equations'], 20, 'Chemical equations are mathematical models that must balance.', _4step('solve','Balance the equation: Fe + O2 -> Fe2O3.','Start with the most complex compound and work outward.','solve','Balance: CH4 + O2 -> CO2 + H2O.','Count carbons first, then hydrogens, then balance oxygen last.','solve','Balance: Al + HCl -> AlCl3 + H2.','Aluminum needs 3 chlorines; adjust HCl accordingly.','experiment','Verify one balanced equation by running the reaction and measuring products.','The product masses should match predictions from the balanced equation.')),
        ('percentage-yield', 'Percent Yield Calculation', ['math.percentages', 'chemistry.stoichiometry'], 20, 'Lab reactions never achieve 100% yield and the actual percentage must be calculated.', _4step('solve','Calculate the theoretical yield from the balanced equation and reactant amounts.','Convert reactant mass to product mass using stoichiometry.','experiment','Run the reaction and carefully collect and weigh the actual product.','Dry the product completely before weighing.','solve','Calculate percent yield: (actual / theoretical) times 100.','This shows what fraction of the possible product was obtained.','compare','Compare yields from two different reaction conditions.','Conditions with higher yield are more efficient.')),
        ('isotopes-atoms', 'Isotope Investigation', ['chemistry.atomic-structure', 'math.equations'], 20, 'Isotopes of elements have different numbers of neutrons affecting atomic mass.', _4step('observe','Compare atoms of the same element with different mass numbers.','Same protons but different neutrons make different isotopes.','solve','Calculate the number of neutrons in each isotope: neutrons = mass number - atomic number.','Atomic number = protons; mass number = protons + neutrons.','solve','Calculate the weighted average atomic mass from isotope masses and abundances.','Average = sum of (mass times abundance fraction) for each isotope.','compare','Compare the calculated average to the periodic table value.','The periodic table shows weighted average atomic mass.')),
        ('lab-safety', 'Lab Safety Protocols', ['chemistry.reactions', 'engineering.design-process'], 18, 'Lab safety procedures prevent accidents through systematic risk assessment.', _4step('observe','Identify five potential hazards in the Laboratory and classify by type.','Chemical, physical, and biological hazards each need different precautions.','match','Match each hazard to the correct safety equipment and procedure.','Chemical spills need different handling than heat burns.','design','Create a safety checklist for a specific experiment.','Include protective equipment, ventilation, and emergency procedures.','predict','Analyze what could go wrong if each safety step is skipped.','Each precaution prevents a specific type of injury or damage.')),
        ('coding-data-analysis', 'Lab Data Analysis Program', ['cs.functions', 'math.statistics'], 20, 'Lab data analysis needs automation for consistent and accurate results.', _4step('code','Write a function that reads a list of measurements and removes outliers.','Define outliers as values more than 2 standard deviations from the mean.','code','Write a function that calculates mean, std dev, and confidence interval.','Confidence interval = mean +/- (z-score times std dev / sqrt(n)).','code','Create a function that plots data and fits a trend line.','Use the data pairs to calculate slope and intercept.','experiment','Test the analysis program with known data sets to verify accuracy.','Compare automated results to hand-calculated values.')),
        ('coding-experiment', 'Experiment Logger', ['cs.data-structures', 'cs.functions'], 20, 'Lab experiments need systematic logging with automated calculations.', _4step('code','Design a data structure for experiment logs: time, measurement, conditions.','Each entry records one measurement with its context.','code','Write a function that adds entries and validates data ranges.','Reject entries with impossible values like negative temperatures in Kelvin.','code','Add a summary function that analyzes trends across the experiment.','Calculate rates of change and identify steady-state conditions.','experiment','Log a complete experiment and verify the summary matches manual analysis.','Run through the full experimental procedure while logging.')),
        ('exponents-half-life', 'Radioactive Half-Life Model', ['math.exponents', 'chemistry.atomic-structure'], 20, 'Radioactive decay follows exponential patterns modeled by half-life.', _4step('observe','Track a simulated radioactive sample as it decays over multiple half-lives.','Count remaining atoms after each half-life period.','solve','Express the decay using exponents: N = N0 times (1/2)^(t/half-life).','After one half-life, N = N0/2; after two, N = N0/4.','solve','Calculate the amount remaining after 5 half-lives.','(1/2)^5 = 1/32 of the original remains.','predict','Predict the age of a sample that has 12.5% of its original radioactive atoms.','12.5% = 1/8 = (1/2)^3, so the sample is 3 half-lives old.')),
        ('scientific-notation-lab', 'Laboratory Scientific Notation', ['math.scientific-notation', 'chemistry.atomic-structure'], 18, 'Lab measurements span many orders of magnitude requiring scientific notation.', _4step('transform','Convert Avogadro number 602,200,000,000,000,000,000,000 to scientific notation.','Move decimal to get 6.022, count 23 places: 6.022 x 10^23.','solve','Multiply two values in scientific notation for a stoichiometry calculation.','Multiply coefficients and add exponents.','solve','Divide values in scientific notation for concentration calculations.','Divide coefficients and subtract exponents.','compare','Express both a mole of atoms and a single atom mass to appreciate the scale.','Contrast 6 x 10^23 atoms with individual atom mass of ~10^-23 g.')),
    ]
    ST = [
        ('machine-lab-analyzer', 'Machine Fragment: Universal Analyzer', ['chemistry.compounds', 'physics.optics'], 22, 'An ancient analyzer identifies any substance composition instantly without consuming the sample.', _4step('experiment','Test the analyzer with ten known compounds and check accuracy.','Use pure reference samples with confirmed composition.','measure','Compare analysis speed and accuracy to modern spectroscopy.','Time each analysis and check composition accuracy.','compare','Test with increasingly complex mixtures to find the limits.','Try pure substances, simple mixtures, and complex compounds.','observe','Examine the analyzer mechanism for clues about its detection method.','Look for any optical, electrical, or chemical detection components.')),
        ('machine-lab-synthesizer', 'Machine Fragment: Matter Synthesizer', ['chemistry.reactions', 'chemistry.compounds'], 22, 'An ancient device creates pure chemical compounds from raw elements with 100% yield.', _4step('experiment','Feed pure elements into the device and document the compounds produced.','Start with simple combinations like hydrogen and oxygen.','measure','Verify the purity and yield of the synthesized compounds.','Compare mass in to mass out for conservation of mass.','compare','Compare the synthesis efficiency to modern chemical production.','Modern reactions rarely achieve 100% yield.','solve','Calculate the theoretical energy required for each synthesis and compare to actual.','Use bond energies to estimate the minimum energy needed.')),
        ('machine-lab-catalyst', 'Machine Fragment: Universal Catalyst', ['chemistry.reactions', 'math.equations'], 22, 'An ancient material catalyzes every reaction it contacts, not just specific ones.', _4step('experiment','Test the catalyst with five different reaction types.','Compare catalyzed vs uncatalyzed reaction rates for each.','measure','Calculate the rate enhancement factor for each reaction type.','Rate factor = catalyzed rate / uncatalyzed rate.','compare','Compare to known catalysts that only work on specific reactions.','Most catalysts are highly specific to one reaction type.','observe','Examine the catalyst surface for structural features.','Look for any changes in the catalyst before and after use.')),
        ('machine-lab-temperature', 'Machine Fragment: Absolute Zero Container', ['physics.thermal-energy', 'chemistry.gas-laws'], 22, 'An ancient container maintains its contents at a temperature approaching absolute zero without refrigeration.', _4step('measure','Measure the internal temperature using the most sensitive available thermometer.','Record multiple readings for accuracy.','experiment','Place different substances inside and observe their behavior at extreme cold.','Note phase changes and any unusual properties at very low temperatures.','compare','Compare the cold achieved to modern cryogenic technology.','Modern methods use liquid helium to reach about 4 Kelvin.','observe','Examine the container construction for insulation clues.','Note the materials and design of the container walls.')),
        ('machine-lab-scale', 'Machine Fragment: Molecular Scale', ['chemistry.atomic-structure', 'math.equations'], 22, 'An ancient scale displays the molecular mass and formula of anything placed on it.', _4step('experiment','Place known compounds on the scale and check if it shows correct formulas.','Start with simple compounds like water and salt.','measure','Compare the displayed molecular masses to calculated values.','Calculate expected molar mass from the periodic table.','compare','Test with complex organic molecules and verify accuracy.','Use compounds with known but complex molecular formulas.','observe','Determine if the scale can distinguish between isomers.','Isomers have the same formula but different structures.')),
        ('machine-lab-containment', 'Machine Fragment: Inert Container', ['chemistry.reactions', 'engineering.materials-science'], 22, 'An ancient container is completely inert and does not react with any substance placed inside.', _4step('experiment','Test the container with the most reactive substances available.','Try strong acids, bases, oxidizers, and fluorine compounds.','measure','Check for any mass change in the container after each test.','Even molecular-level reactions would cause detectable mass changes.','compare','Compare the inertness to modern PTFE and glass containers.','Note which substances react with modern containers but not the ancient one.','observe','Examine the container material under magnification.','Look for any surface structure that might explain the inertness.')),
        ('machine-lab-clock', 'Machine Fragment: Reaction Timer', ['chemistry.reactions', 'math.equations'], 22, 'An ancient device predicts exactly how long any chemical reaction will take before it starts.', _4step('experiment','Set up five reactions and record the device predictions before starting each.','Note the predicted completion time for each reaction.','measure','Time each reaction to completion and compare to the prediction.','Calculate the prediction error for each reaction.','solve','Analyze what factors the device might consider to make accurate predictions.','Consider concentration, temperature, catalyst presence, and activation energy.','compare','Compare prediction accuracy to modern kinetics calculations.','Modern predictions require detailed knowledge of rate constants.')),
    ]
    return _make_biome_quests('laboratory', S, ST)

def explorers_map():
    S = [
        ('grid-coordinates', 'Grid Reference Navigation', ['math.coordinate-geometry', 'math.equations'], 20, 'The Explorer Map uses grid references that need mastering for accurate navigation.', _4step('observe','Study the coordinate grid system on the Explorer Map.','Note how x increases east and y increases north.','solve','Convert between map coordinates and real-world distances using the map scale.','Scale 1:1000 means 1 cm on map = 10 m in reality.','navigate','Navigate to a location given only its grid coordinates.','Walk the x-distance east then the y-distance north from origin.','solve','Calculate the straight-line distance between two coordinate points.','Distance = sqrt((x2-x1)^2 + (y2-y1)^2).')),
        ('bearing-compass', 'Compass Bearing Navigation', ['math.geometry', 'physics.forces'], 20, 'Navigation requires compass bearings that combine angles with direction.', _4step('measure','Take compass bearings to three visible landmarks.','Hold the compass level and read the bearing in degrees from north.','solve','Calculate the bearing from one landmark to another.','Bearings are measured clockwise from north: 0-360 degrees.','navigate','Follow a three-leg route using only compass bearings and distances.','Walk each bearing for the specified distance.','solve','Calculate the return bearing to get back to the starting point.','The return bearing is the original plus 180 degrees, modulo 360.')),
        ('scale-distance', 'Map Scale and Distance', ['math.proportions', 'math.ratios'], 18, 'Map distances must be converted to real distances using the scale factor.', _4step('measure','Measure three distances on the map between known landmarks.','Use a ruler for precise measurements in centimeters.','solve','Convert each map distance to real distance using the scale.','Real distance = map distance times scale denominator.','compare','Verify the calculated distances by pacing between the actual landmarks.','Count paces and multiply by average pace length.','predict','Predict the real distance for a new route measured on the map.','Apply the same scale conversion to the new measurement.')),
        ('triangulation', 'Position by Triangulation', ['math.geometry', 'math.equations'], 22, 'An unknown position can be found by taking bearings to known landmarks.', _4step('measure','Take compass bearings from your position to three known landmarks.','Record each bearing precisely.','solve','Draw back-bearings from each landmark on the map.','Reverse each bearing by adding 180 degrees and draw the line.','solve','Find the intersection point of the three back-bearing lines.','The intersection is your approximate position.','experiment','Verify the triangulated position using a known reference point.','Walk to the nearest known point and check the distance matches.')),
        ('elevation-contour', 'Contour Map Reading', ['math.equations', 'physics.forces'], 20, 'Contour lines on maps show elevation changes that affect travel planning.', _4step('observe','Study the contour map and identify steep slopes vs gentle slopes.','Close-together contour lines mean steep terrain.','measure','Determine the elevation change between two points using contour intervals.','Count the number of contour lines crossed and multiply by the interval.','solve','Calculate the average slope between two points: rise over run.','Rise = elevation change; run = horizontal distance.','predict','Predict which route between two points requires the least climbing.','The route crossing fewest contour lines has the least elevation change.')),
        ('indirect-height', 'Indirect Height Measurement', ['math.proportions', 'math.geometry'], 20, 'Tall objects can be measured indirectly using shadows and proportional reasoning.', _4step('measure','Measure the shadow of a tall landmark and a stick of known height at the same time.','Both shadows are cast at the same angle.','solve','Set up the proportion: tall object / its shadow = stick / its shadow.','Cross-multiply and solve for the unknown height.','experiment','Verify by measuring at different times of day.','The proportion should give the same height regardless of shadow length.','solve','Calculate the height using trigonometry: height = distance times tan(angle).','Measure the angle of elevation to the top and the distance to the base.')),
        ('area-territory', 'Territory Area Calculation', ['math.area-volume', 'math.coordinate-geometry'], 20, 'Explored territories need area calculation for mapping and resource estimation.', _4step('measure','Plot the territory boundary as coordinate points on the grid map.','Record x,y coordinates at each boundary corner.','solve','Calculate the area using the shoelace formula for polygons.','Sum the cross-products of consecutive vertices.','compare','Compare the calculated area to the estimated area from grid counting.','Both methods should give similar results.','predict','Estimate the resources in the territory based on area and resource density.','Resources = area times average resource per unit area.')),
        ('speed-distance-time', 'Travel Speed Calculations', ['physics.velocity', 'math.equations'], 18, 'Exploration routes need time estimates based on speed and distance.', _4step('measure','Time how long it takes to travel a known distance at walking pace.','Record distance in meters and time in seconds.','solve','Calculate walking speed: speed = distance / time.','Express in meters per second or km per hour.','predict','Predict travel time for a 5 km route at the calculated speed.','Time = distance / speed.','compare','Compare travel times on flat vs hilly terrain.','Uphill travel is slower; adjust the speed estimate for elevation.')),
        ('vector-navigation', 'Vector Addition for Navigation', ['physics.forces', 'math.equations'], 22, 'Navigation with wind or current requires vector addition of movement and drift.', _4step('solve','Calculate the resultant displacement from two perpendicular movement vectors.','Use Pythagorean theorem: resultant = sqrt(a^2 + b^2).','solve','Determine the direction of the resultant using arctan(y/x).','The angle gives the bearing of the actual path.','predict','Predict the actual landing point when crossing a river with current.','Add the downstream drift vector to the cross-river movement vector.','solve','Calculate the heading needed to compensate for a known crosswind.','Aim upstream enough that the drift carries you to the target.')),
        ('percentage-explored', 'Exploration Coverage Percentage', ['math.percentages', 'math.area-volume'], 18, 'The percentage of the map that has been explored needs tracking.', _4step('measure','Calculate the total area of the explorable map region.','Use the map boundaries and scale to find total area.','solve','Calculate the area explored so far from expedition records.','Sum the areas of all mapped regions.','solve','Calculate the percentage explored: explored / total times 100.','Express as a percentage of the total area.','predict','Estimate how many more expeditions are needed to reach 90% coverage.','Divide remaining area by average area explored per expedition.')),
        ('probability-terrain', 'Terrain Encounter Probability', ['math.probability', 'math.statistics'], 18, 'Different terrain types are encountered with different probabilities on exploration routes.', _4step('collect','Record the terrain type every 100 meters along five different routes.','Classify each point as forest, grassland, mountain, or water.','solve','Calculate the probability of each terrain type from the data.','Probability = count of type / total observation points.','predict','Predict the expected terrain distribution on a new planned route.','Apply the probabilities to the route length.','compare','Compare actual terrain on the new route to predictions.','Note any significant deviations from the predicted distribution.')),
        ('pythagorean-distance', 'Straight-Line Distance', ['math.pythagorean-theorem', 'math.coordinate-geometry'], 18, 'The shortest distance between two points often requires Pythagorean calculations.', _4step('measure','Record the east-west and north-south distances between two exploration camps.','These are the two legs of a right triangle.','solve','Calculate the straight-line distance using the Pythagorean theorem.','Hypotenuse = sqrt(east-west^2 + north-south^2).','compare','Compare the straight-line distance to the actual walking route distance.','Walking routes are always longer than straight-line distances.','solve','Calculate the bearing of the straight-line path using arctan.','Bearing = arctan(east-west distance / north-south distance).')),
        ('statistics-expedition', 'Expedition Data Statistics', ['math.statistics', 'math.equations'], 18, 'Expedition data on daily distances needs statistical analysis for planning.', _4step('collect','Record daily distances traveled for the past 10 expeditions.','Note the total distance for each expedition day.','solve','Calculate mean, median, and standard deviation of daily distances.','These statistics describe typical and variable performance.','predict','Plan a route that can be completed within a 95% confidence interval.','Route distance should be within mean minus 2 std deviations times days.','compare','Compare performance across different terrain types.','Categorize days by terrain and compare statistics.')),
        ('coding-pathfinder', 'Pathfinding Algorithm', ['cs.algorithms', 'math.coordinate-geometry'], 22, 'An exploration route planner needs a pathfinding algorithm.', _4step('code','Create a grid representation of the terrain map with traversability values.','Each grid cell has a cost based on terrain difficulty.','code','Implement a simple pathfinding algorithm that finds a route between two points.','Try a greedy approach that always moves toward the goal.','code','Improve the algorithm to consider terrain costs and find the easiest path.','Weight the path by terrain difficulty, not just distance.','experiment','Compare the algorithm route to a hand-planned route for the same journey.','Check total cost and distance for both routes.')),
        ('coding-survey', 'Survey Data Collector', ['cs.data-structures', 'cs.functions'], 20, 'Exploration surveys need a digital collection and analysis tool.', _4step('code','Design a data structure for survey points with coordinates, elevation, and features.','Each point stores its location and what was found there.','code','Write a function to add survey points and calculate distance from previous point.','Track the cumulative distance of the survey route.','code','Create a summary function that reports total distance, elevation range, and feature counts.','Aggregate statistics across all survey points.','experiment','Enter data from a real survey and verify the summary matches manual calculations.','Cross-check automated totals against hand-counted values.')),
        ('linear-elevation', 'Elevation Profile Modeling', ['math.linear-functions', 'physics.forces'], 20, 'Elevation changes along a route follow patterns that can be modeled mathematically.', _4step('measure','Record elevation at 10 equally spaced points along a route.','Use the altimeter at each marked waypoint.','solve','Plot elevation vs distance and identify linear sections.','Straight segments on the plot indicate constant slope.','solve','Calculate the slope of each linear section.','Slope = elevation change / horizontal distance.','predict','Predict the elevation at an unmeasured point using the linear model.','Interpolate within the linear section.')),
        ('ratio-map-features', 'Map Feature Ratios', ['math.ratios', 'biology.ecosystems'], 18, 'Different landscape features appear in characteristic ratios that aid navigation.', _4step('count','Count the occurrences of five different landscape features in a map section.','Record streams, hills, clearings, rock formations, and ponds.','solve','Express the feature counts as ratios relative to the most common.','If streams are most common at 20, hills at 10 gives a 2:1 ratio.','compare','Compare feature ratios across different map regions.','Similar geology should show similar feature ratios.','predict','Predict the expected feature counts in a new unsurveyed region.','Apply the characteristic ratios to the new region area.')),
        ('equation-pace-count', 'Pace Count Equations', ['math.equations', 'math.proportions'], 18, 'Navigation by pace count requires calibration equations for different terrain.', _4step('measure','Calibrate pace count over a known 100-meter distance on flat ground.','Count paces for three passes and average.','solve','Create a paces-to-distance conversion equation: distance = paces / pace_factor.','The pace factor is paces per 100 meters.','experiment','Test the equation accuracy over a longer known distance.','Walk 500 meters and compare calculated vs actual distance.','solve','Adjust the equation for uphill terrain where paces are shorter.','Multiply the flat-ground factor by a terrain correction of about 1.2 for moderate hills.')),
        ('history-exploration', 'Age of Exploration', ['history.exploration', 'math.coordinate-geometry'], 22, 'Ancient maps in the Explorer archives document historical exploration routes.', _4step('observe','Study three historical maps showing exploration routes and territorial claims.','Note the dates, routes, and claimed territories.','compare','Compare the accuracy of historical maps to modern maps of the same areas.','Note what the early explorers got right and wrong.','solve','Calculate the total distance of a historical exploration route from the map.','Use the map scale to convert map distances.','predict','Predict what challenges the historical explorers faced based on terrain analysis.','Consider distance, elevation, water crossings, and climate.')),
        ('migration-patterns', 'Animal Migration Mapping', ['biology.ecosystems', 'math.coordinate-geometry'], 20, 'Animal migration routes cross the Explorer Map and need documentation.', _4step('observe','Track and plot the migration path of a herd across the map.','Record coordinates at daily intervals.','measure','Calculate the total migration distance and average daily distance.','Sum all daily segment distances for the total.','solve','Determine the bearing and speed of migration from the coordinate data.','Bearing from consecutive points; speed = distance / time.','predict','Predict where the herd will be in one week based on current heading and speed.','Project the current trajectory forward seven days.')),
    ]
    ST = [
        ('machine-map-compass', 'Machine Fragment: Perfect Compass', ['physics.forces', 'math.geometry'], 22, 'An ancient compass points toward something other than magnetic north with unwavering accuracy.', _4step('observe','Carry the compass through different areas and record where it points.','Note the heading in multiple locations.','measure','Triangulate the location the compass points toward.','Draw lines from multiple positions in the pointing direction.','experiment','Test whether the target changes over time or with conditions.','Check the compass at the same locations at different times.','compare','Compare the compass accuracy to modern magnetic and gyro compasses.','Note which has less deviation and better reliability.')),
        ('machine-map-telescope', 'Machine Fragment: Distance Telescope', ['physics.optics', 'math.equations'], 22, 'An ancient telescope displays the exact distance to whatever it is aimed at.', _4step('measure','Point the telescope at objects of known distance and check accuracy.','Compare displayed distance to measured distance.','experiment','Test the maximum range of the distance measurement.','Point at increasingly distant objects.','compare','Compare accuracy to modern laser rangefinders.','Note which is more accurate at various distances.','solve','Reverse-engineer the measurement principle from the behavior patterns.','Analyze whether it uses parallax, time-of-flight, or some other method.')),
        ('machine-map-tracker', 'Machine Fragment: Path Memory', ['cs.data-structures', 'math.coordinate-geometry'], 22, 'An ancient device records every path taken by its carrier and can replay any route.', _4step('experiment','Carry the device on a known route and check if it records the path.','Walk a specific route then examine the device for recorded data.','measure','Compare the recorded path accuracy to actual GPS-measured coordinates.','Check position accuracy at multiple waypoints.','compare','Compare recording density and accuracy to modern GPS tracking.','Note waypoint spacing and positional accuracy.','solve','Calculate the total distance from the recorded path data.','Sum all segment distances between consecutive recorded points.')),
        ('machine-map-weather', 'Machine Fragment: Weather Oracle', ['physics.thermal-energy', 'math.probability'], 22, 'An ancient device predicts weather at any mapped location with extraordinary accuracy.', _4step('observe','Record device weather predictions for five locations over three days.','Note predicted temperature, precipitation, and wind.','measure','Compare predictions to actual weather at each location.','Calculate prediction accuracy for each variable.','compare','Compare accuracy to modern weather forecast services.','Note how far ahead each method maintains good accuracy.','solve','Analyze what variables the device might use for its predictions.','Consider atmospheric pressure, temperature gradients, and humidity.')),
        ('machine-map-terrain', 'Machine Fragment: Living Map', ['math.coordinate-geometry', 'biology.ecosystems'], 22, 'An ancient map surface reshapes itself to show real-time terrain changes.', _4step('observe','Watch the map surface for changes over several days.','Note any areas where the terrain representation shifts.','measure','Compare map changes to actual terrain surveys of the same areas.','Check if map changes match real erosion, flooding, or vegetation changes.','compare','Compare the update speed to modern satellite mapping capabilities.','Note how quickly each reflects real-world changes.','experiment','Create a deliberate terrain change and see if the map responds.','Move a visible marker and check if the map updates.')),
        ('machine-map-guide', 'Machine Fragment: Navigation Spirit', ['math.equations', 'physics.forces'], 22, 'An ancient crystal hums when pointed toward the optimal path, considering terrain and weather.', _4step('experiment','Follow the crystal guidance on three different journeys and record the routes.','Compare crystal-guided routes to planned direct routes.','measure','Compare total travel time and effort for guided vs direct routes.','Time each journey and rate difficulty.','solve','Analyze why the guided routes might be faster despite being longer.','Consider terrain difficulty, elevation changes, and obstacle avoidance.','compare','Compare the crystal routing to modern GPS route optimization.','Note which finds better routes in different terrain types.')),
        ('machine-map-boundary', 'Machine Fragment: Territory Marker', ['math.area-volume', 'physics.waves'], 22, 'Ancient boundary stones create an invisible perimeter that can be sensed but not seen.', _4step('observe','Walk along the boundary and document where you sense the perimeter.','Record coordinates at each point where the boundary is detected.','measure','Map the complete boundary shape from the sensor data.','Connect the detection points to form the perimeter outline.','solve','Calculate the enclosed area from the boundary coordinates.','Use the coordinate geometry area formula.','experiment','Test whether the boundary can be adjusted by moving the stones.','Relocate one stone and check if the boundary shifts.')),
    ]
    return _make_biome_quests('explorers-map', S, ST)


def _gen_biome(biome, quests_data, stories_data):
    """Generate biome from compact quest data."""
    return _make_biome_quests(biome, quests_data, stories_data)

def time_rift():
    S = [
        ('constitution-articles', 'Constitution Articles', ['history.us-constitution', 'history.government'], 22, 'The Time Rift opens to the Constitutional Convention showing the framework of government being debated.', _4step('observe','Examine the original document structure and identify its seven articles.','Each article establishes a different component of government.','match','Match each article to the branch or function it creates.','Article I creates the legislature; II the executive; III the judiciary.','compare','Compare the powers given to each branch and how they check each other.','Each branch has specific powers to limit the other two.','teach','Explain why the founders chose separation of powers.','Concentrated power was what they fought a revolution to escape.')),
        ('amendments-process', 'Amendment Process', ['history.us-constitution', 'math.ratios'], 20, 'The Time Rift shows the amendment process and the mathematics of ratification.', _4step('observe','Study the amendment process from proposal to ratification.','Amendments need 2/3 of Congress to propose and 3/4 of states to ratify.','solve','Calculate the exact numbers: 2/3 of 100 senators and 3/4 of 50 states.','67 senators and 38 states are needed.','compare','Compare the difficulty of amending to passing a regular law.','Simple majority vs supermajority requirements.','predict','Predict how the amendment threshold affects what amendments get passed.','Only widely supported changes can clear such a high bar.')),
        ('civil-war-battles', 'Civil War Turning Points', ['history.civil-war', 'math.statistics'], 22, 'The Time Rift reveals key Civil War battles whose outcomes turned the tide.', _4step('explore','Investigate three major battles: Gettysburg, Vicksburg, and Antietam.','Note the date, location, forces, and outcome of each.','sequence','Arrange key Civil War events in chronological order from 1861 to 1865.','Start with Fort Sumter and end with Appomattox.','solve','Analyze the strategic importance of each battle using territory and supply data.','Consider how each battle affected territory, morale, and resources.','compare','Compare Union and Confederate military strategies throughout the war.','The Union focused on blockade and division; the Confederacy on defense.')),
        ('reconstruction-era', 'Reconstruction Amendments', ['history.civil-war', 'history.us-constitution'], 22, 'The Time Rift shows the 13th, 14th, and 15th Amendments transforming the nation after the Civil War.', _4step('decode','Read and interpret each Reconstruction amendment.','13th ends slavery; 14th ensures equal protection; 15th protects voting rights.','compare','Compare the legal rights before and after these amendments.','Document the specific rights each amendment guarantees.','solve','Analyze the gap between the legal promises and actual implementation.','Consider how enforcement legislation and court decisions affected outcomes.','predict','Predict how these amendments would later become foundations for civil rights movements.','The equal protection clause became the basis for landmark court cases.')),
        ('industrial-tech', 'Industrial Revolution Technology', ['history.industrial-revolution', 'physics.work-energy'], 22, 'The Time Rift reveals how key inventions transformed manufacturing and daily life.', _4step('observe','Examine three key Industrial Revolution inventions: steam engine, spinning jenny, telegraph.','Note what each invention replaced and how it changed production.','solve','Calculate the productivity increase from hand manufacturing to machine production.','Compare output per worker per hour before and after mechanization.','compare','Compare working conditions in cottage industry vs factory system.','Consider hours, safety, wages, and living conditions.','predict','Predict which modern technologies might cause similar societal disruption.','Consider AI, automation, and other transformative technologies.')),
        ('labor-movement', 'Labor Movement Origins', ['history.industrial-revolution', 'economics.market-structures'], 22, 'The Time Rift shows workers organizing in response to industrial working conditions.', _4step('observe','Study the conditions that led workers to form the first labor unions.','Note wages, hours, safety, and treatment of different worker groups.','compare','Compare the demands of early labor unions to modern worker protections.','Many early demands became modern labor laws.','solve','Analyze the economic effects of collective bargaining on wages and productivity.','Compare wages and output before and after unionization.','predict','Predict how labor-management relations affect economic growth.','Consider the balance between worker welfare and business efficiency.')),
        ('wwi-technology', 'WWI Military Technology', ['history.world-war-1', 'engineering.design-process'], 22, 'The Time Rift reveals how new technologies changed the nature of warfare in WWI.', _4step('observe','Examine three new technologies: machine guns, poison gas, and tanks.','Note how each changed tactical possibilities.','compare','Compare the effect of these technologies on offensive vs defensive strategy.','Machine guns favored defense; tanks were developed to break the stalemate.','solve','Analyze how trench warfare resulted from the balance of new weapons.','When defense is stronger than offense, both sides dig in.','predict','Predict how each new technology influenced the development of the next generation of weapons.','Technologies often develop in response to countermeasures.')),
        ('great-depression', 'Great Depression Economics', ['history.world-war-2', 'economics.gdp'], 22, 'The Time Rift opens to the Great Depression showing economic collapse and recovery efforts.', _4step('observe','Examine the economic indicators leading up to the 1929 crash.','Look at stock prices, bank loans, and consumer spending patterns.','solve','Calculate the percentage decline in GDP, employment, and stock values during the Depression.','Compare peak values to trough values.','compare','Compare New Deal programs to modern economic stimulus approaches.','Both use government spending to stimulate economic recovery.','predict','Analyze which factors were most important in causing and ending the Depression.','Consider banking practices, trade policy, and government intervention.')),
        ('wwii-theaters', 'WWII Global Theaters', ['history.world-war-2', 'math.coordinate-geometry'], 22, 'The Time Rift shows WWII battles across multiple theaters that need strategic analysis.', _4step('observe','Map the European, Pacific, and North African theaters of WWII on a world map.','Note the major battle locations and dates in each theater.','sequence','Arrange key events chronologically: invasion of Poland through V-J Day.','Track the timeline across all three theaters simultaneously.','compare','Compare Allied strategies in the European vs Pacific theaters.','The European strategy focused on a two-front land invasion; Pacific on island-hopping.','solve','Analyze how geography and logistics influenced strategy in each theater.','Distance, terrain, and supply lines constrained what was possible.')),
        ('wwii-homefront', 'WWII Home Front', ['history.world-war-2', 'economics.market-structures'], 20, 'The Time Rift reveals how civilians supported the war effort through rationing and production.', _4step('observe','Examine rationing programs and their allocation of scarce resources.','Note which goods were rationed and how ration points worked.','solve','Calculate how rationing mathematics ensured fair distribution.','Total supply divided by population gives per-person allocation.','compare','Compare wartime economic controls to peacetime free markets.','Government control replaced market pricing for essential goods.','predict','Predict the economic effects of ending wartime controls suddenly.','Supply shortages could cause inflation as pent-up demand is released.')),
        ('immigration-urbanization', 'Immigration and Urbanization', ['history.industrial-revolution', 'math.statistics'], 22, 'The Time Rift shows waves of immigration transforming American cities.', _4step('observe','Study immigration patterns and the growth of industrial cities from 1880-1920.','Note where immigrants came from and where they settled.','solve','Calculate the percentage population growth of three cities during this period.','Growth rate = (new - old) / old times 100.','compare','Compare push factors in home countries to pull factors in America.','Push: poverty, war; Pull: jobs, freedom, opportunity.','predict','Predict how rapid urbanization affected housing, sanitation, and public health.','Rapid growth often outpaces infrastructure development.')),
        ('progressive-era', 'Progressive Era Reforms', ['history.us-constitution', 'economics.market-structures'], 22, 'The Time Rift shows reformers addressing corruption and inequality in the early 1900s.', _4step('observe','Examine three major Progressive Era reforms: food safety, antitrust, and suffrage.','Note what problem each reform addressed.','compare','Compare the problems reformers fought to modern regulatory issues.','Many Progressive Era solutions created agencies that still exist.','solve','Analyze how investigative journalism drove public support for reform.','Calculate the timeline from exposure to legislation for key reforms.','predict','Predict which current issues might drive future reform movements.','Look for patterns similar to Progressive Era conditions.')),
        ('timeline-calculation', 'Historical Timeline Math', ['math.equations', 'history.us-constitution'], 18, 'Historical events need mathematical analysis of dates, durations, and intervals.', _4step('solve','Calculate the years between the Constitution ratification and the Civil War start.','1788 to 1861 = 73 years.','solve','Calculate the percentage of US history spent in various eras.','Divide each era length by total years since founding.','sequence','Arrange 12 events spanning US history in correct chronological order.','Use dates to verify the ordering.','predict','Calculate the midpoint date between two historical events.','Average the two dates for the midpoint.')),
        ('statistics-census', 'Historical Census Data', ['math.statistics', 'history.industrial-revolution'], 20, 'Census data through the Time Rift reveals population trends over American history.', _4step('collect','Record US population at each census decade from 1790 to 1920.','Note the population for each decade.','solve','Calculate the growth rate between each census.','Rate = (new - old) / old times 100 for each decade.','solve','Determine if population growth was linear or exponential during this period.','Plot the data and check the curve shape.','predict','Predict the 1930 population based on historical growth patterns.','Extend the growth trend forward one decade.')),
        ('percentage-history', 'Historical Percentage Analysis', ['math.percentages', 'history.world-war-2'], 18, 'Historical events involve percentage calculations for casualties, production, and economics.', _4step('solve','Calculate military casualties as a percentage of total population for three wars.','Percentage = casualties / population times 100.','compare','Compare casualty percentages across different wars and nations.','Higher percentages indicate greater relative impact.','solve','Calculate the percentage increase in industrial production during WWII.','Compare pre-war and wartime production figures.','predict','Analyze how wartime production percentage increases affected the post-war economy.','Massive production capacity often transitions to consumer goods.')),
        ('probability-history', 'Historical Cause Analysis', ['math.probability', 'history.world-war-1'], 20, 'Historical events have multiple causes whose relative importance can be analyzed.', _4step('observe','Identify five factors that contributed to the outbreak of WWI.','Consider alliances, nationalism, imperialism, militarism, and the assassination.','solve','Assign weight to each factor based on historical evidence.','More evidence of causal connection gets a higher weight.','compare','Compare different historians assessments of the most important factor.','Historians disagree about which factor was most critical.','predict','Predict whether the war could have been avoided if any single factor was different.','Consider counterfactual scenarios for each factor.')),
        ('equations-economic', 'Economic History Equations', ['math.equations', 'economics.gdp'], 20, 'Economic trends in history follow mathematical relationships that can be modeled.', _4step('collect','Record GDP values at five-year intervals during a historical growth period.','Use the economic data archives.','solve','Fit a linear or exponential equation to the growth data.','Try both models and see which fits better.','solve','Calculate the growth rate from the equation parameters.','Linear: rate = slope; Exponential: rate = base.','predict','Predict economic output 10 years beyond the data using the model.','Substitute the future date into the equation.')),
        ('coordinate-timeline', 'Timeline Coordinate System', ['math.coordinate-geometry', 'history.us-constitution'], 18, 'Historical events can be plotted on a coordinate system with time and geography as axes.', _4step('design','Create a coordinate system with time on x-axis and geographic location on y-axis.','Use years for x and a numeric code for regions as y.','place','Plot 15 major events on the coordinate timeline.','Each event gets an (x,y) point based on when and where it happened.','solve','Calculate the rate of westward expansion from the plotted data.','Rate = change in geographic position / change in time.','pattern','Identify clusters of events that indicate historical turning points.','Clusters suggest periods of rapid change or crisis.')),
        ('coding-timeline', 'Historical Database', ['cs.data-structures', 'cs.functions'], 20, 'Historical events need a searchable database for research.', _4step('code','Design a data structure for historical events: year, name, type, region, significance.','Each event record stores all relevant attributes.','code','Write search functions to find events by year range, type, or region.','Filter records based on the specified criteria.','code','Create a timeline function that orders events chronologically and displays them.','Sort by year and format for display.','experiment','Load 30 historical events and test all search and display functions.','Verify searches return correct results and the timeline is properly ordered.')),
        ('coding-comparison', 'Historical Comparison Tool', ['cs.functions', 'math.statistics'], 20, 'A comparison tool needs to analyze parallel aspects of different historical periods.', _4step('code','Write a function that accepts two time periods and compares their economic data.','Compare GDP growth, population, and production values.','code','Add a function that identifies similarities and differences between periods.','Flag attributes that differ by more than 20%.','code','Create a summary function that generates a comparison report.','Format the differences and similarities clearly.','experiment','Compare the Industrial Revolution and post-WWII economic booms.','Verify the tool identifies known similarities and differences.')),
    ]
