if __name__ == '__main__':
    total = 0
    for biome_slug, (var_name, fn) in BIOMES.items():
        quests = fn()
        n = write_biome(biome_slug, var_name, quests)
        total += n
        print(f'  {biome_slug}: {n} quests')
    print(f'\nTotal: {total} quests across {len(BIOMES)} biomes')

    # Generate index.ts for builder
    index_lines = ['// Builder tier quest barrel export']
    index_lines.append('')
    index_lines.append("import type { CreateQuestInput } from '../../../types/quest.js';")
    index_lines.append('')
    for biome_slug, (var_name, _) in BIOMES.items():
        index_lines.append(f"export {{ {var_name} }} from './builder-{biome_slug}.js';")
    index_lines.append('')
    fp = os.path.join(OUTDIR, 'index.ts')
    with open(fp, 'w') as f:
        f.write('\n'.join(index_lines) + '\n')
    print(f'\nWrote {fp}')

